import subprocess,re,json,hashlib,html
R=Path(__file__).resolve().parent;D=R/'dist'
BASE='389a9f0c4ecfcd486e2aa79cefbd4a8ecbc05e1c'
def old(rel):return subprocess.check_output(['git','show',BASE+':'+rel],cwd=R).decode()
def main(s):return re.search(r'<main id="main">(.*?)</main>',s,re.S).group(1)
def page_intro(k,title,desc):return f'<div class="page-intro"><div class="eyebrow">{k}</div><h1>{title}</h1><p class="lede">{desc}</p></div>'
def chapter(n,title,body,id=None):return f'<section class="chapter"'+(f' id="{id}"' if id else '')+f'><div class="chapter-label">{n}</div><div><h2>{title}</h2>{body}</div></section>'
def link(url,title,desc='',tag=''):
 return f'<a class="atlas-card" href="{url}">'+(f'<span class="eyebrow">{tag}</span>' if tag else '')+f'<h3>{title}</h3>'+ (f'<p>{desc}</p>' if desc else '')+'<span class="card-arrow" aria-hidden="true">→</span></a>'
def grid(*xs):return '<div class="atlas-grid">'+''.join(xs)+'</div>'
def actions(*xs):return '<div class="actions">'+''.join(f'<a class="text-link" href="{u}">{t} →</a>' for u,t in xs)+'</div>'
html_paths=subprocess.check_output(['git','ls-tree','-r','--name-only',BASE,'dist'],cwd=R,text=True).splitlines()
originals={str(Path(x).relative_to('dist')):old(x) for x in html_paths if x.endswith('.html')}
for rel,content in originals.items():(D/rel).write_text(content)
template=originals['index.html']
def make(rel,title,body,page='editorial'):
 t=template
 t=re.sub(r'<title>.*?</title>',f'<title>{title} · Unified Dynamics</title>',t)
 t=re.sub(r'data-page="[^"]+"',f'data-page="{page}"',t,count=1)
 t=re.sub(r'<main id="main">.*?</main>','<main id="main">'+body+'</main>',t,flags=re.S)
 p=D/rel;p.parent.mkdir(parents=True,exist_ok=True);p.write_text(t)
# Home: orient a new reader before offering the archive.
figure=re.search(r'<figure>.*?</figure>',template,re.S).group(0)
home=f'''<section class="hero"><div><div class="eyebrow">Unified Dynamics · A reading guide</div><h1>Structure first.<br><em>Follow the evidence.</em></h1><p class="lede">How does a finite structure constrain motion, observation and persistence?</p><p>Unified Dynamics starts with explicit tetrahedral carriers. This atlas guides you from their mathematics to declared models, then to the tests needed for a physical correspondence.</p><div class="actions"><a class="button" href="/primer/">Begin with the foundations <span>→</span></a><a class="text-link" href="/research/">Browse the research programmes →</a></div></div>{figure}</section><div class="status-strip"><div>Finite mathematics <b>Scoped results</b></div><div>Independent review <b>Scope-specific / pending</b></div><div>Physical promotion <b>0</b></div></div>'''
home+=chapter('01','A clear route through the programme.',grid(link('/primer/','Understand the foundations','The carrier, its evolution and what an observation can recover.','Start here'),link('/research/','Explore a research question','Follow the source, geometry, observation, action or parity programme.','Then explore'),link('/evidence/','Assess the evidence','Separate finite results, constructor certificates and physical tests.','Then evaluate')))
home+=chapter('02','Find the level of detail you need.', '<div class="atlas-reading-list"><a href="/papers/"><strong>Read a paper</strong><span>Core review papers and topic-organized theorem manuscripts.</span><b>→</b></a><a href="/archive/"><strong>Inspect the record</strong><span>Sources, dependencies, coefficients, captures and corrections.</span><b>→</b></a><a href="/contribution/"><strong>Contribute a review</strong><span>Bound a claim, reproduce a result or qualify a bridge.</span><b>→</b></a></div>')
home+=chapter('03','A programme you can examine one result at a time.','<p>Developed by <strong>Benjamin Walker Mayes</strong>, with AI-assisted mathematical and computational work. Each result keeps its declared carrier, assumptions, version and evidence status.</p><p>The mathematical models do not by themselves establish a physical identification. Reviews and negative results belong in the same record.</p>'+actions(('https://orcid.org/0009-0002-5813-0724','Researcher profile'),('/updates/','Dated updates')))
make('index.html','Unified Dynamics',home,'home')
p=D/'index.html';p.write_text(p.read_text().replace('<h2>Find the level of detail you need.</h2>','<h2 id="research-record-navigation">Find the level of detail you need.</h2>'))
