research+='<div class="atlas-jump"><a href="#source">Source & events</a><a href="#geometry">Metrics & refinement</a><a href="#observation">Observation</a><a href="#action">Action & stability</a><a href="#parity">Parity transport</a></div>'
research+=chapter('01','What selects an event or a persistent record?', '<p><span class="atlas-label">Current scope</span> A typed response contract and prepared finite mechanisms. The source law selecting a native response remains a separate premise.</p><ol class="atlas-sequence"><li><a href="/source-contract/"><strong>Define the response contract</strong><span>What must be supplied before the outcome is known?</span></a></li><li><a href="/source-programme/"><strong>Inspect a prepared candidate</strong><span>State, stock, feedback and renewal assumptions.</span></a></li><li><a href="/realization/"><strong>Test native realization</strong><span>Which Hodge-to-programme bridges are obstructed?</span></a></li><li><a href="/joint-carrier/"><strong>Account for the complete carrier</strong><span>History windows and retained resources.</span></a></li><li><a href="/programmed-clock/"><strong>Inspect the supplied clock</strong><span>Internal timing and what native dynamics must still supply.</span></a></li></ol><p class="atlas-next"><strong>Open gate:</strong> source-selected preparation and dynamics, with a complete physical realization.</p>','source')
research+=chapter('02','What selects the metric, scale and refinement?', '<p><span class="atlas-label">Current scope</span> Exact compatibility and nonselection results under declared carrier, metric and transfer conventions.</p><ol class="atlas-sequence"><li><a href="/native-admission/"><strong>Test the native operator</strong><span>Spectra, residual floors and endpoint aliases.</span></a></li><li><a href="/metric-admission/"><strong>Declare the metric</strong><span>Separate conventions and full-clock exclusions.</span></a></li><li><a href="/subdivision/"><strong>Check a refinement interface</strong><span>Norm, boundary and generator compatibility.</span></a></li><li><a href="/metric-selection/"><strong>Expose selection premises</strong><span>What a source rule fixes and what remains free.</span></a></li><li><a href="/refinement-tower/"><strong>Carry calibration across levels</strong><span>Keep the detail state and its resources.</span></a></li><li><a href="/history-comparison/"><strong>Compare complete histories</strong><span>Equal coarse codes do not identify retained histories.</span></a></li></ol><p class="atlas-next"><strong>Open gate:</strong> a native source commitment selecting the metric, observable and refinement.</p>','geometry')
research+=chapter('03','What can a shell reveal about the dynamics?', '<p><span class="atlas-label">Current scope</span> Finite 600-cell observability, conditioning, preparation and calibration contracts, plus constructor-side spectral and phase certificates.</p>'+grid(link('/observation/','Read the observation programme','Start with the observer, visible and hidden directions, and the finite acquisition contract.'),link('/research-record/#observation-continuation','Inspect the estimator continuation','Later timing, two-step noise, encoded projection and actual SVD certificates.'))+'<p class="atlas-next"><strong>Open gate:</strong> attributable external replay, uniform estimator guarantees where claimed, and metrology. Synthetic records are not apparatus observations.</p>','observation')
research+=chapter('04','Which backgrounds and perturbations remain stable?', '<p><span class="atlas-label">Current scope</span> A declared gauge-covariant action, reduced modes, curved branches and conditional preparation, energy and source-work bounds.</p>'+grid(link('/papers/#action-construction','Begin with the action','Transport, reciprocal dynamics, constraints, reduced modes and resonance analysis.'),link('/papers/#curved-branches','Follow the curved branches','Existence, color modes, residual constraints and observable readout.'),link('/papers/#quantitative-admission','Inspect quantitative admission','Nonlinear trapping, endpoint errors, preparation, energy and source-work budgets.'))+'<p class="atlas-next"><strong>Open gate:</strong> physical realization and eligible measurement records satisfying the full input contract.</p>'+actions(('/evidence/measurable-audit/','Read the realization and dataset audit')),'action')
research+=chapter('05','What does retained parity transport actually establish?', '<p><span class="atlas-label">Current scope</span> A source-recovered finite selected sector, a typed transport repair and a prospective numerical admission contract.</p>'+grid(link('/research/parity/','Read the parity programme','The finite object, repaired map, historical receipt scope and next review gate.'))+'<p class="atlas-next"><strong>Open gate:</strong> non-constructor review of the new contract before a separately frozen blind campaign; physical parity remains unestablished.</p>','parity')
make('research/index.html','Research programmes',research)
# A current synthesis separates the parity question from its archival chronology.
parity=page_intro('Research / Parity transport','A finite transport result.<br>A separate physical question.','Start with the selected six-dimensional sector and the typed map; inspect the historical receipts only after their scope is clear.')
parity+=chapter('01','The object being transported.','<p>The finite carrier is the 30-dimensional oriented boundary of a 4-simplex, with the declared unit metric. A source convention selects a rank-six Hodge sector and a 30×6 Darboux frame W.</p><p>The selector and finite frame construction have exact constructor checks. The lower-response selection is a supplied structural convention; the calculation does not derive a dynamical preference for it.</p>'+actions(('/research-record/#parity','Read the source construction and its limits'),('/sources/?q=parity','Find the parity source records')))
parity+=chapter('02','Keep the maps in their spaces.','<p>W embeds six event coordinates into the selected carrier. T=Wᵀ returns them. The retained map I<sub>c</sub> has reciprocal blocks c and 1/c, and R reverses the second three coordinates.</p><div class="equation">T Θ W I<sub>c</sub> = I<sub>c</sub> R</div><p>The explicit W makes the composite well typed. Θ squares to the selected projector on the ambient space; no parity on the complement is supplied. These are conditional internal transport identities.</p>')
parity+=chapter('03','The prospective test is a new contract.','<p>The v0.1 admission contract checks source hashes, selected-sector membership, the native generator, Darboux pullback, definitions and the full composite. It rejects nonpositive or nonfinite c and uses one declared row-sum residual norm.</p><p>Its numeric lane is 0.001≤c≤1000. A successful verdict is <strong>NUMERICAL_SOURCE_ADMITTED</strong>. Public constructor fixtures are development tests, not a new blind cohort or an exact radical certificate.</p>'+actions(('/sources/research-record-v0.1/parity-contract/CONTRACT.json','Read the frozen contract'),('/research-record/#2026-10-19T130822Z-codex-parity-contract-50d3c586','Inspect the versioned evidence')))
parity+=chapter('04','Historical replication and current review are different records.','<p>The recovered historical record reports an external-AI Gemini replication and a CRL2d ruling, with the rider <em>transport consistency, not dynamical discovery</em>. The receipt files and full ruling document are recovered. Named or signed original approval and the committed raw Gemini output remain unresolved.</p><p>Those historical labels are preserved. They are not independent-human review or a laboratory measurement. The prospective contract needs attributable non-constructor review before a new blind campaign.</p>'+actions(('/research-record/#custody','Read the custody distinctions'),('/evidence/','Assess the evidence boundary'),('/contribution/','Contribute a bounded review')))
make('research/parity/index.html','Parity transport',parity)
# Archive is an intentional index, not the default reading surface.
