archive+=chapter('01','Trace a claim to its source.',grid(link('/sources/','Source registry','Search preserved source text, downloads, hashes and scope.'),link('/dependencies/','Dependency explorer','Inspect the frozen finite proof graph and premise-change scenarios.'),link('/reconciliation/','Corrections & dispositions','See how source assertions were qualified, corrected or superseded.'),link('/ledger/','Coefficient ledger','Read the later 448-row ledger with its original bins and next gates.')))
archive+=chapter('02','Inspect calculations and research returns.',grid(link('/research-record/','Capture register','Search the pinned repository snapshot, public reports and execution receipts.'),link('/observation/#main','Observation source edition','Read the finite-model session and its 26-source original compilation.'))+'<p class="muted">A captured report, merged pull request or deployment receipt records custody. Each scientific result retains its own verification and review scope.</p>')
