archive+=chapter('04','Return something reviewable.','<p>Choose an exact claim or package version. State what you checked, your independence, the input hashes and the scope of any pass, failure or open finding.</p>'+actions(('/contribution/','Review and contribution guide'),('https://github.com/ud-tetra/UD','Research repository')))
