paper+='<div class="atlas-jump"><a href="#core-papers">Core papers</a><a href="#action-construction">Action</a><a href="#curved-branches">Curved branches</a><a href="#quantitative-admission">Admission & error</a><a href="#observation-papers">Observation</a><a href="#narrative">Narrative</a></div>'
