u=main(originals['updates/index.html']);ups=list(re.finditer(r'<article\b.*?</article>',u,re.S));assert len(ups)>=35
update=page_intro('Dated updates','What changed,<br>and where to read it.','Recent editorial and research notes. Current explanations live under Foundations and Research; original returns and older planning notes stay in the archive.')
update+='<article class="claim" id="atlas-hierarchy-v02"><div class="eyebrow">19 October 2026 · Editorial reconciliation v0.2</div><h2>A reading hierarchy replaces the flat page list</h2><p>Six main destinations now separate foundations, research programmes, evidence, papers and the archive. Specialist pages keep their URLs; paper collections follow the argument, and capture logs are secondary to the programme summaries.</p><p>This changes presentation and navigation. Source statuses, scientific claim data and historical evidence remain preserved.</p><a class="text-link" href="/sources/atlas-structure-v0.2/EDITORIAL_RECONCILIATION.json">Editorial change record ↓</a></article>'
